# ============================================================================
# Script de entrega: correccion de "apertura" en el dashboard de Franquicias
# ============================================================================
# Que hace:
#  - Agrega club_abierto / fecha_apertura a contrato_franquicia_detalles
#  - Corrige la logica del dashboard para usar club_abierto en vez de inferirlo
#    (mal) de fecha_proximo_pago_regalias
#  - Agrega el campo al formulario y al expediente del contrato
#  - Incluye el script de datos que marca Cuatro Caminos como abierto
#    (30 may 2026), deja Escobedo/Izazaga/Melt Polanco como aun no abiertos, y
#    pone fecha de apertura tentativa al resto del historico
#
# Como usarlo:
#   1) Corre este script desde la raiz del repo (fpt-contratos) en PowerShell.
#   2) Revisa los cambios con "git status" / "git diff".
#   3) git add -A ; git commit -m "..." ; git push
#   4) Luego, con la DATABASE_URL de produccion en un .env local (ver guia que
#      te di antes), corre DESDE backend/:
#        npm run migrate:franquicia-club-abierto
#        npm run fix:franquicias-club-abierto
#      y borra el .env al terminar.
# ============================================================================

function Write-FileFromBase64 {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )
    $fullPath = Join-Path (Get-Location) $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "Escrito: $RelativePath"
}

